<script setup lang="ts">
import { computed, ref } from 'vue'
import { onLoad, onShow, onUnload } from '@dcloudio/uni-app'
import { useMessage, useToast } from 'wot-design-uni'
import { useClosetStore } from '../../stores/closet'
import { closetApi } from '../../services/api'
import { HttpError } from '../../services/http'
import { canvasBridge, navigateOutfitLink } from '../../services/outfit'
import { canvasExecution, stopCanvasRun } from '../../services/outfit-runtime'
import { soundEnabled, toggleSound } from '../../services/sound'
import { recommendApi } from '../../recommend/api'
import { boardSignature, workspace, createBoard, addBoard, openSavedBoard, mutateBoard, storageWarning, discardWorkspace, findOpenOutfit, dedupeOpenOutfits, type WorkspaceBoard, type OutfitWorkspace } from '../../domain/outfit-workspace'
import { activeWorkspace, pruneAgentWorkspaces, createWorkspace, listWorkspaces, workspaceSummary, removeWorkspace, renameWorkspace, setActiveWorkspace, type WorkspaceInfo } from '../../domain/workspace-registry'
import { normalizeScene, type Outfit, type OutfitDraft } from '../../domain/outfit'
import { isMissingOutfit } from '../../domain/outfitErrors'
import BoardEditor from '../../components/outfit/BoardEditor.vue'
import OutfitThumbnail from '../../components/outfit/OutfitThumbnail.vue'
import OutfitReview from '../../components/outfit/OutfitReview.vue'
import ExplainButton from '../../components/outfit/ExplainButton.vue'
const closet = useClosetStore(), toast = useToast(), message = useMessage()
const space = ref<OutfitWorkspace | null>(null), wsId = ref('main'), workspaces = ref<WorkspaceInfo[]>([]), counts = ref<Record<string, number>>({})
const active = computed(() => space.value?.boards.find(b => b.id === space.value?.activeId)), wsName = computed(() => workspaces.value.find(w => w.id === wsId.value)?.name || '默认画板')
const focus = ref(true), loading = ref(false), error = ref(''), saving = ref(false), wearing = ref(false), wearingId = ref('')
const checked = ref<string[]>([]), boardsOpen = ref(false), libraryOpen = ref(false), saved = ref<Outfit[]>([]), libraryLoading = ref(false), libraryError = ref(''), librarySearch = ref('')
const filteredSaved = computed(() => saved.value.filter(o => o.name.toLocaleLowerCase().includes(librarySearch.value.trim().toLocaleLowerCase())))
const wsOpen = ref(false), moreOpen = ref(false), infoOpen = ref(false), reviewOpen = ref(false), conflicts = ref<string[]>([])
const boardModal = ref(false), newBoardName = ref(''), boardTarget = ref('main'), wsModal = ref(false), wsMode = ref<'create' | 'rename'>('create'), wsInput = ref('')
const editor = ref<InstanceType<typeof BoardEditor> | null>(null)
const currentRun = computed(() => canvasExecution.workspaceId === wsId.value && !!canvasExecution.runId)
const isSaved = computed(() => !!active.value?.outfitId && boardSignature(active.value) === active.value.savedSignature)
const readyForOotd = computed(() => isSaved.value && !active.value?.locked && !active.value?.error)
const saveTargets = computed(() => focus.value ? active.value ? [active.value] : [] : checked.value.length ? space.value?.boards.filter(b => checked.value.includes(b.id)) || [] : active.value ? [active.value] : [])
const availableBoards = computed(() => space.value?.boards.filter(b => !b.locked) || [])
const allChecked = computed(() => !!availableBoards.value.length && availableBoards.value.every(b => checked.value.includes(b.id)))
const wsOptions = computed(() => workspaces.value.map(w => ({ value: w.id, label: `${w.name}${w.kind === 'agent' ? '（临时）' : ''}` })))
let owner = '', routeQuery: Record<string, string | undefined> = {}, initialized = false
function refreshWorkspaces() { if (!owner) return; workspaces.value = listWorkspaces(owner); counts.value = Object.fromEntries(workspaces.value.map(w => [w.id, workspaceSummary(owner, w.id).boards])) }
function switchWorkspace(id: string) { wsId.value = id; space.value = workspace(owner, id); if (!id.startsWith('agent:')) setActiveWorkspace(owner, id); if (!space.value.activeId && space.value.boards.length) space.value.activeId = space.value.boards[0].id; checked.value = []; focus.value = false; wsOpen.value = false; refreshWorkspaces() }
function selectBoard(board: WorkspaceBoard) { if (!space.value) return; space.value.activeId = board.id; focus.value = true; boardsOpen.value = false; if (currentRun.value && canvasExecution.boardId !== board.id) canvasExecution.following = false }
function titleChange(value: string) { const board = active.value; if (board && !board.locked && board.name !== value) { board.name = value; board.contentVersion++ } }
function openAssistant() { uni.navigateTo({ url: `/pkg-outfit/assistant/index?from=workspace&workspace=${encodeURIComponent(wsId.value)}${active.value ? '&board=' + encodeURIComponent(active.value.id) : ''}` }) }
function back() { uni.switchTab({ url: '/pages/outfits/index' }) }
async function loadRoute() {
  loading.value = true; error.value = ''
  try {
    await closet.ensureUser(); if (!closet.user) throw new Error('登录已失效。'); owner = closet.user.username
    pruneAgentWorkspaces(owner); wsId.value = routeQuery.session ? `agent:${routeQuery.session}` : routeQuery.workspace || activeWorkspace(owner)
    space.value = workspace(owner, wsId.value); if (!wsId.value.startsWith('agent:')) setActiveWorkspace(owner, wsId.value)
    dedupeOpenOutfits(owner, wsId.value); refreshWorkspaces()
    const id = routeQuery.id
    if (id && id !== 'new') {
      const found = findOpenOutfit(owner, id, wsId.value)
      if (found) { switchWorkspace(found.workspaceId); space.value!.activeId = found.boardId; focus.value = true }
      else {
        const outfit = await closetApi.outfit(id), board = openSavedBoard(space.value!, outfit)
        const key = `yixu.outfit-draft.v1:${owner}:${id}`
        let draft: OutfitDraft | null = null; try { draft = JSON.parse(uni.getStorageSync(key) || 'null') } catch { /* Ignore malformed legacy draft. */ }
        if (draft?.scene && [1, 2].includes(draft.scene.version)) { board.name = draft.name; board.scene = normalizeScene(draft.scene); board.revision = draft.revision; board.status = '本机草稿'; if (draft.revision !== outfit.revision) { board.error = '原搭配已在另一处更新。请另存副本，或重新打开最新版本。'; conflicts.value.push(board.id) } uni.removeStorageSync(key) }
      }
    } else if (id === 'new') {
      const suffix = routeQuery.draft ? ':' + routeQuery.draft : '', key = `yixu.outfit-draft.v1:${owner}:new${suffix}`
      let draft: OutfitDraft | null = null; try { draft = JSON.parse(uni.getStorageSync(key) || 'null') } catch { /* Ignore malformed legacy draft. */ }
      const existing = space.value!.boards.find(b => b.id === (suffix ? `legacy${suffix}` : 'legacy:new'))
      if (existing) space.value!.activeId = existing.id
      else { const board = draft?.scene && [1, 2].includes(draft.scene.version) ? createBoard(draft.name, draft.scene, suffix ? `legacy${suffix}` : 'legacy:new') : createBoard(); addBoard(space.value!, board); uni.removeStorageSync(key) }
      focus.value = true
    } else focus.value = false
    if (routeQuery.board) { const board = space.value!.boards.find(b => b.id === routeQuery.board); if (board) selectBoard(board); else error.value = '这块临时组合台不在当前设备上。请在原设备查看，或重新生成。' }
    if (!space.value!.activeId && space.value!.boards.length) space.value!.activeId = space.value!.boards[0].id
    canvasBridge.value = {
      context: () => { const b = active.value, selected = b?.scene.elements.find(e => b.selectedIds.includes(e.elementId || e.garmentId) && e.kind !== 'PERSON_PART'); return { route: '/outfits/workspace', workspaceId: wsId.value, boardId: b?.id, boardCount: space.value?.boards.length, contentVersion: b?.contentVersion, outfitId: b?.outfitId, revision: b?.revision, name: b?.name, selectedIds: b?.selectedIds || [], garmentId: selected?.garmentId, scene: b?.scene } },
      apply: (scene, title) => { const b = active.value; if (!b || b.locked) throw new Error('请先选中可编辑组合台。'); mutateBoard(b, scene); if (title) b.name = title },
      save: async () => { if (!active.value) throw new Error('请先选中组合台。'); await saveBoards([active.value], true) },
    }
    initialized = true
  } catch (e) { error.value = e instanceof Error ? e.message : '工作区无法加载。' } finally { loading.value = false }
}
function newBoard() { refreshWorkspaces(); if (workspaces.value.length < 2) { createBoardIn(wsId.value); return } newBoardName.value = ''; boardTarget.value = wsId.value; boardModal.value = true }
function createBoardIn(target: string, name = '') { try { const next = workspace(owner, target); if (next.boards.length >= 12) throw new Error('这个画板已经放满十二个组合台，请先保存并关闭几个，或换一个画板。'); if (target !== wsId.value) switchWorkspace(target); addBoard(next, createBoard(name.trim() || undefined)); space.value = next; boardModal.value = false; focus.value = true; refreshWorkspaces() } catch (e) { toast.warning(e instanceof Error ? e.message : String(e)) } }
function workspaceForm(mode: 'create' | 'rename') { wsMode.value = mode; wsInput.value = mode === 'rename' ? wsName.value : ''; wsModal.value = true; wsOpen.value = false }
function submitWorkspace() { try { if (wsMode.value === 'create') { const info = createWorkspace(owner, wsInput.value); refreshWorkspaces(); switchWorkspace(info.id); toast.success(`已新建画板「${info.name}」。`) } else { renameWorkspace(owner, wsId.value, wsInput.value); refreshWorkspaces(); toast.success('画板已改名。') } wsModal.value = false } catch (e) { toast.error(e instanceof Error ? e.message : String(e)) } }
async function deleteWorkspace() { const id = wsId.value, target = space.value; if (!target || id === 'main') return; if (target.boards.some(b => b.locked)) { toast.warning('Agent 正在操作组合台，请等待完成或先停止操作。'); return } const unsaved = target.boards.filter(b => b.scene.elements.length && boardSignature(b) !== b.savedSignature).length; try { await message.confirm({ title: `删除画板「${wsName.value}」？`, msg: `将移除这个画板里的 ${target.boards.length} 个组合台${unsaved ? `，其中 ${unsaved} 个还没有保存到搭配库，草稿会丢失` : ''}。已经保存到搭配库的搭配会保留。`, confirmButtonText: '删除画板', cancelButtonText: '先留着' }) } catch { return } if (target.boards.some(b => b.locked)) { toast.warning('Agent 已开始操作，画板仍然保留。'); return } switchWorkspace('main'); discardWorkspace(owner, id); removeWorkspace(owner, id); refreshWorkspaces(); toast.success('画板已删除。') }
async function library() { libraryOpen.value = true; libraryLoading.value = true; libraryError.value = ''; try { saved.value = await closetApi.outfits() } catch (e) { libraryError.value = e instanceof Error ? e.message : '搭配列表暂时无法加载。' } finally { libraryLoading.value = false } }
function openOutfit(outfit: Outfit) { try { const found = findOpenOutfit(owner, outfit.id, wsId.value); if (found) { switchWorkspace(found.workspaceId); space.value!.activeId = found.boardId } else openSavedBoard(space.value!, outfit); libraryOpen.value = false; focus.value = true } catch (e) { toast.warning(e instanceof Error ? e.message : String(e)) } }
function toggleChecked(id: string, value: boolean) { checked.value = value ? [...new Set([...checked.value, id])] : checked.value.filter(v => v !== id) }
async function discardBoards(boards: WorkspaceBoard[], one = false) { const target = space.value, removable = boards.filter(b => !b.locked); if (!target || !removable.length) return; const unsaved = removable.some(b => b.scene.elements.length && boardSignature(b) !== b.savedSignature); if (unsaved || !one) { try { await message.confirm({ title: one ? '关闭这块未保存组合台？' : `丢弃所选 ${removable.length} 块组合台？`, msg: one ? '关闭会移除这块本机草稿。可以先保存到搭配库，再关闭。' : '未保存的本机草稿会被移除。已保存到搭配库的搭配仍会保留。', confirmButtonText: one ? '关闭并丢弃' : '丢弃所选组合台', cancelButtonText: one ? '保留组合台' : '继续保留' }) } catch { return } } const ids = new Set(removable.filter(b => !b.locked).map(b => b.id)); target.boards = target.boards.filter(b => !ids.has(b.id)); checked.value = checked.value.filter(id => !ids.has(id)); if (ids.has(target.activeId)) target.activeId = target.boards[0]?.id || ''; if (!target.boards.length) focus.value = false; refreshWorkspaces() }
async function writeBoard(board: WorkspaceBoard, copy = false, overwrite = false) {
  if (board.locked) throw new Error('请先停止 Agent 并接手，或等待操作结束。')
  if (!board.scene.elements.length) throw new Error(`${board.name}：请先加入贴纸。`)
  if (!board.name.trim()) throw new Error('请先给搭配起个名字。')
  if (conflicts.value.includes(board.id) && !copy) throw new Error('另一处已更新这套搭配，你的草稿仍保留。请重新加载或另存副本。')
  const id = copy ? null : overwrite ? board.sourceOutfitId || null : board.outfitId || null, revision = overwrite ? board.sourceRevision : board.revision
  let result: Outfit
  try { result = await closetApi.saveOutfit(id, id ? revision ?? null : null, board.name.trim(), board.scene) }
  catch (e) { if (id && isMissingOutfit(e)) { result = await closetApi.saveOutfit(null, null, board.name.trim(), board.scene); toast.warning(`「${board.name}」原来的搭配在服务器上已不存在，已另存为新搭配，内容没有丢。`) } else { if (e instanceof HttpError && (e.status === 409 || e.code === 'OUTFIT_VERSION_CONFLICT')) conflicts.value = [...new Set([...conflicts.value, board.id])]; throw e } }
  board.outfitId = result.id; board.revision = result.revision; board.scene = normalizeScene(result.scene); board.contentVersion++; board.savedSignature = boardSignature(board); board.status = '已保存'; board.error = ''; board.sourceOutfitId = undefined; board.sourceRevision = undefined; conflicts.value = conflicts.value.filter(id => id !== board.id); uni.$emit('closet-outfit-saved')
}
async function saveBoards(boards = saveTargets.value, propagate = false) { const pending = boards.filter(b => !b.locked && b.scene.elements.length && boardSignature(b) !== b.savedSignature); if (!pending.length) { if (propagate && boards.some(b => b.locked)) throw new Error('请先停止 Agent 并接手，或等待操作结束。'); toast.info('所选组合台已保存、正在操作或仍为空。'); return } if (pending.length > 1 || pending[0].sourceOutfitId && !pending[0].outfitId) { try { await message.confirm({ title: pending.length > 1 ? `保存 ${pending.length} 套搭配？` : '如何保存调整后的搭配？', msg: pending.length > 1 ? '每块组合台独立保存到账号。部分失败时只需重试失败项；批量保存调整副本时默认另存。' : '原搭配仍未改变。可以另存一套，或覆盖原搭配；版本冲突时保留草稿。', confirmButtonText: pending.length > 1 ? '确认保存' : '另存新搭配', cancelButtonText: '取消' }) } catch { if (propagate) throw new Error('已取消保存。'); return } } saving.value = true; const failures: string[] = []; try { for (const b of pending) { try { await writeBoard(b); checked.value = checked.value.filter(id => id !== b.id) } catch (e) { b.error = e instanceof Error ? e.message : '保存失败'; failures.push(`${b.name}：${b.error}`) } } if (failures.length) { error.value = failures.join('\n'); toast.error(`有 ${failures.length} 块组合台未保存，成功项已保留。`); if (propagate) throw new Error(error.value) } else { error.value = ''; toast.success(`已保存 ${pending.length} 套搭配。`) } refreshWorkspaces() } finally { saving.value = false } }
async function saveCopy(overwrite = false) { const b = active.value; if (!b) return; try { await message.confirm({ title: overwrite ? '确认覆盖原搭配？' : '另存为新搭配？', msg: overwrite ? '将用这块临时组合台替换原搭配。版本冲突时不会覆盖，草稿仍保留。' : '保留当前草稿并保存为独立搭配，原搭配不变。', confirmButtonText: overwrite ? '确认覆盖' : '另存新搭配', cancelButtonText: '取消' }) } catch { return } saving.value = true; try { await writeBoard(b, !overwrite, overwrite); toast.success(overwrite ? '原搭配已更新。' : '已另存新搭配。'); error.value = '' } catch (e) { b.error = e instanceof Error ? e.message : '保存失败。'; toast.error(b.error) } finally { saving.value = false } }
async function loadLatest() { const b = active.value; if (!b?.outfitId) return; try { await message.confirm({ title: '重新加载账号中的搭配？', msg: '当前本机修改将被替换，可先另存副本。', confirmButtonText: '重新加载', cancelButtonText: '保留草稿' }) } catch { return } try { const o = await closetApi.outfit(b.outfitId); b.name = o.name; b.revision = o.revision; mutateBoard(b, o.scene); b.savedSignature = boardSignature(b); b.error = ''; b.status = '已保存'; conflicts.value = conflicts.value.filter(id => id !== b.id); error.value = '' } catch (e) { toast.error(e instanceof Error ? e.message : '重新加载失败。') } }
async function wear() { const b = active.value; if (!b?.outfitId) return; wearing.value = true; try { await recommendApi.wear({ outfitId: b.outfitId }); wearingId.value = b.outfitId; toast.success('已记下今天穿了这套。') } catch (e) { toast.error(e instanceof Error ? e.message : '没有记录成功。') } finally { wearing.value = false } }
function ootd() { if (!readyForOotd.value) { toast.info('请先保存当前搭配，再生成 OOTD。'); return } uni.setStorageSync('yixu.route-query:ootd', `outfit=${encodeURIComponent(active.value!.outfitId!)}`); uni.switchTab({ url: '/pages/ootd/index' }) }
const moreActions = computed(() => [{ name: '新组合台' }, { name: '打开已有搭配' }, { name: '搭配说明与保存状态', disabled: !active.value }, { name: '导出当前搭配', disabled: !active.value?.scene.elements.length || !focus.value }, { name: '另存副本', disabled: !active.value || !!active.value.locked }, { name: '覆盖原搭配', disabled: !active.value?.sourceOutfitId || !!active.value.outfitId || !!active.value.locked }, { name: '重命名画板', disabled: wsId.value === 'main' || wsId.value.startsWith('agent:') }, { name: '删除这个画板', disabled: wsId.value === 'main' || currentRun.value, color: '#bd4b4b' }, { name: soundEnabled.value ? '关闭音效' : '开启音效' }])
function moreAction(e: { index: number }) { moreOpen.value = false; if (e.index === 0) newBoard(); else if (e.index === 1) void library(); else if (e.index === 2) infoOpen.value = true; else if (e.index === 3) void editor.value?.exportPng(); else if (e.index === 4) void saveCopy(); else if (e.index === 5) void saveCopy(true); else if (e.index === 6) workspaceForm('rename'); else if (e.index === 7) void deleteWorkspace(); else toggleSound() }
onLoad(query => { routeQuery = query || {}; void loadRoute() })
onShow(() => { if (initialized) refreshWorkspaces() })
onUnload(() => { if (canvasBridge.value?.context().workspaceId === wsId.value) canvasBridge.value = null })
</script>
<template><view class="page">
  <wd-skeleton v-if="loading" :row-col="[{ width: '80%' }, { height: '600rpx' }]" /><template v-else-if="space"><view class="spread"><wd-button type="text" size="small" @click="back">返回搭配库</wd-button><wd-button type="text" size="small" @click="openAssistant">问鱼搭助手</wd-button></view><wd-input v-if="focus && active" :model-value="active.name" :disabled="!!active.locked" :maxlength="100" placeholder="给搭配起个名字" @update:model-value="titleChange" /><view v-else class="heading">{{ wsId.startsWith('agent:') ? '临时搭台' : '穿搭工作区' }}</view><view class="spread section"><wd-button plain size="small" @click="refreshWorkspaces(); wsOpen = true">{{ wsName }} ▾</wd-button><text class="small">{{ space.boards.length }} 个组合台{{ wsId.startsWith('agent:') ? ' · 临时' : '' }}</text></view><text v-if="focus && active" class="line small">{{ active.locked ? 'Agent 正在搭配' : isSaved ? '已保存到搭配库' : '草稿自动保留在此设备，尚未保存到搭配库' }}</text>
    <view class="actions section"><wd-button size="small" plain :disabled="!active || !!active.locked" @click="reviewOpen = true">穿搭检查</wd-button><wd-button size="small" plain :disabled="!readyForOotd" @click="ootd">OOTD</wd-button><wd-button size="small" plain @click="boardsOpen = true">组合台 · {{ space.boards.length }}</wd-button><wd-button size="small" plain :disabled="!space.boards.length" @click="focus = !focus">{{ focus ? '总览' : '聚焦' }}</wd-button><wd-button size="small" :loading="saving" :disabled="!saveTargets.some(b => !b.locked && b.scene.elements.length > 0)" @click="saveBoards()">{{ !focus && checked.length ? `保存 ${checked.length} 套` : '保存' }}</wd-button><wd-button size="small" type="text" @click="moreOpen = true">更多</wd-button></view>
    <view v-if="routeQuery.from === 'recommend'" class="notice section">来自推荐 · 这是一份草稿，保存前可以随意调整<ExplainButton v-if="routeQuery.run && routeQuery.key" :run-id="routeQuery.run" :outfit-key="routeQuery.key" label="查看依据" /></view><view v-if="storageWarning.text || error" class="notice warning section">{{ storageWarning.text || error }}</view><view v-if="currentRun" class="notice section"><wd-loading size="32rpx" /><text class="line">{{ canvasExecution.label || '正在准备搭配' }}</text><wd-button size="small" type="error" plain @click="stopCanvasRun()">停止并接手</wd-button></view>
    <template v-if="focus && active"><view v-if="conflicts.includes(active.id) || active.error" class="notice warning section">{{ conflicts.includes(active.id) ? '另一处已更新这套搭配，你的草稿仍保留。' : active.error }}<view class="actions"><wd-button v-if="active.outfitId" size="small" plain @click="loadLatest">重新加载</wd-button><wd-button size="small" @click="saveCopy()">另存副本</wd-button></view></view><view class="section"><BoardEditor :key="active.id" ref="editor" :board="active" /></view><wd-button v-if="isSaved" block plain :loading="wearing" :disabled="wearingId === active.outfitId" @click="wear">{{ wearingId === active.outfitId ? '已记录今天穿了' : '今天穿了' }}</wd-button></template>
    <view v-else class="section stack"><view v-for="(b, i) in space.boards" :key="b.id" class="artboard"><view class="spread"><text>{{ i + 1 }} · {{ b.name }}</text><wd-checkbox :model-value="checked.includes(b.id)" :disabled="!!b.locked" @change="toggleChecked(b.id, $event.value)" /></view><view class="section" @tap="selectBoard(b)"><OutfitThumbnail :scene="b.scene" :title="b.name" /></view><view class="spread section"><text class="small">{{ b.locked ? '搭配中' : boardSignature(b) === b.savedSignature ? '已保存' : b.status }}</text><wd-button size="small" type="text" :disabled="!!b.locked" @click="discardBoards([b], true)">关闭组合台</wd-button></view></view><view v-if="!space.boards.length" class="empty"><view class="title">把今天想穿的，放在一起。</view><text class="subtitle">{{ wsId.startsWith('agent:') ? 'Agent 的方案会在这里逐步搭起来。临时结果只保留在此设备。' : '每块组合台一套搭配，放在一起看看，再决定穿哪套。' }}</text><wd-button @click="newBoard">新建第一个组合台</wd-button></view></view>
  </template><view v-else class="stack"><view class="notice error">{{ error }}</view><wd-button @click="loadRoute">重新加载画板</wd-button><wd-button plain @click="back">返回搭配列表</wd-button></view>
  <wd-popup v-model="boardsOpen" position="bottom" closable><view class="sheet"><view class="sheet-head">工作区组合台</view><text class="line small">{{ wsName }} · {{ space?.boards.length || 0 }} / 12 块 · {{ checked.length ? `已选择 ${checked.length} 块` : '草稿自动保留在此设备' }}</text><wd-checkbox :model-value="allChecked" @change="checked = $event.value ? availableBoards.map(b => b.id) : []">全选可管理组合台</wd-checkbox><view v-for="(b, i) in space?.boards || []" :key="b.id" class="row"><wd-checkbox :model-value="checked.includes(b.id)" :disabled="!!b.locked" @change="toggleChecked(b.id, $event.value)" /><view class="row-body" @tap="selectBoard(b)"><text>{{ i + 1 }} · {{ b.name }}</text><text class="line small">{{ b.locked ? '搭配中' : boardSignature(b) === b.savedSignature ? '已保存' : '本机草稿' }}</text></view><wd-button type="text" size="small" :disabled="!!b.locked" @click="discardBoards([b], true)">关闭</wd-button></view><wd-status-tip v-if="!space?.boards.length" image="content" tip="新建组合台，开始一套搭配" /><view class="stack section"><wd-button plain :disabled="(space?.boards.length || 0) >= 12" @click="boardsOpen = false; newBoard()">新组合台</wd-button><wd-button :loading="saving" @click="saveBoards(checked.length ? space?.boards.filter(b => checked.includes(b.id)) : active ? [active] : [])">保存所选 {{ checked.length || (active ? 1 : 0) }} 套</wd-button><wd-button type="error" plain :disabled="!checked.length" @click="discardBoards(space?.boards.filter(b => checked.includes(b.id)) || [])">丢弃所选 {{ checked.length }} 块</wd-button></view></view></wd-popup>
  <wd-popup v-model="wsOpen" position="bottom" closable><view class="sheet"><view class="sheet-head">选择画板</view><wd-cell v-for="w in workspaces" :key="w.id" :title="w.name + (w.kind === 'agent' ? '（临时）' : '')" :value="`${counts[w.id] || 0} 个组合台${w.id === wsId ? ' ✓' : ''}`" clickable @click="switchWorkspace(w.id)" /><wd-button block plain @click="workspaceForm('create')">新建画板</wd-button></view></wd-popup>
  <wd-popup v-model="wsModal" position="bottom" closable :z-index="30"><view class="sheet"><view class="sheet-head">{{ wsMode === 'create' ? '新建画板' : '重命名画板' }}</view><wd-input v-model="wsInput" :maxlength="20" placeholder="画板名称，1 到 20 个字" /><view class="section"><wd-button block :disabled="!wsInput.trim()" @click="submitWorkspace">{{ wsMode === 'create' ? '新建画板' : '保存名称' }}</wd-button></view></view></wd-popup>
  <wd-popup v-model="boardModal" position="bottom" closable :z-index="30"><view class="sheet"><view class="sheet-head">新组合台</view><wd-input v-model="newBoardName" placeholder="搭配名称（可不填）" :maxlength="100" /><wd-picker v-model="boardTarget" label="放入画板" :columns="wsOptions" /><wd-button block @click="createBoardIn(boardTarget, newBoardName)">新建组合台</wd-button></view></wd-popup>
  <wd-popup v-model="libraryOpen" position="bottom" closable><view class="sheet"><view class="sheet-head">打开已有搭配</view><wd-search v-model="librarySearch" placeholder="搜索搭配名称" hide-cancel /><wd-loading v-if="libraryLoading" /><view v-else-if="libraryError" class="notice error">{{ libraryError }}<wd-button type="text" @click="library">重新加载</wd-button></view><wd-status-tip v-else-if="!filteredSaved.length" image="content" :tip="saved.length ? '没有找到这套搭配' : '还没有保存的搭配'" /><view v-for="o in filteredSaved" :key="o.id" class="row" @tap="openOutfit(o)"><view class="library-thumb"><OutfitThumbnail :scene="o.scene" /></view><view class="row-body"><text>{{ o.name }}</text><text class="line small">{{ o.scene.elements.length }} 张贴纸</text></view><wd-button size="small" plain @click.stop="openOutfit(o)">打开</wd-button></view></view></wd-popup>
  <wd-popup v-model="infoOpen" position="bottom" closable><view class="sheet"><view class="sheet-head">搭配说明与保存状态</view><template v-if="active"><text class="title">{{ active.name }}</text><text class="line">{{ active.reason || '自由搭配，满意后再保存。' }}</text><text class="line">{{ active.status }}</text><text class="line">{{ active.scene.elements.length }} 张贴纸</text><text class="line small">{{ isSaved ? '已保存到搭配库' : '本机草稿，尚未保存到搭配库' }}</text><text v-if="active.sourceOutfitId" class="line small">这是原搭配的调整副本；默认另存，不会自动覆盖原搭配。</text></template></view></wd-popup>
  <OutfitReview v-if="active" v-model="reviewOpen" :scene="active.scene" /><wd-action-sheet v-model="moreOpen" :actions="moreActions" cancel-text="取消" @select="moreAction" /><wd-toast /><wd-message-box />
</view></template>
<style lang="scss" scoped>@import '../../components/outfit/outfit.scss';.artboard{background:$surface;border:1rpx solid $line;border-radius:$radius-lg;padding:24rpx}.empty{padding:100rpx 16rpx;text-align:center}.library-thumb{width:120rpx;flex-shrink:0}</style>
